import java.util.*;
class Solution {
    public List<Long> minOperations(int[] nums, int[] queries) {
        int n = nums.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nums[i];
        Arrays.sort(a);
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
        List<Long> res = new ArrayList<>();
        for (int q : queries) {
            int k = (int)(Arrays.binarySearch(a, q) >= 0 ? upper(a, q) : upper(a, q));
            k = upper(a, q);
            res.add((long) q * k - pre[k] + (pre[n] - pre[k]) - (long) q * (n - k));
        }
        return res;
    }
    private int upper(long[] a, long q) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int mid = (lo + hi) >>> 1; if (a[mid] <= q) lo = mid + 1; else hi = mid; }
        return lo;
    }
}

