class Solution {
public:
    vector<long long> minOperations(vector<int>& nums, vector<int>& queries) {
        int n = nums.size(), m = queries.size();
        vector<int> a = nums;
        sort(a.begin(), a.end());
        vector<int> ord(m);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int x, int y){ return queries[x] < queries[y]; });
        vector<long long> res(m);
        long long pre = 0, total = accumulate(a.begin(), a.end(), 0LL);
        int j = 0;
        for (int qi : ord) {
            long long q = queries[qi];
            while (j < n && a[j] <= q) pre += a[j++];
            res[qi] = q * j - pre + (total - pre) - q * (n - j);
        }
        return res;
    }
};

