import java.util.*;
class Solution {
    public List<Long> minOperations(int[] nums, int[] queries) {
        int n = nums.length, m = queries.length;
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nums[i];
        Arrays.sort(a);
        Integer[] ord = new Integer[m];
        for (int i = 0; i < m; i++) ord[i] = i;
        Arrays.sort(ord, (x, y) -> queries[x] - queries[y]);
        long total = 0; for (long v : a) total += v;
        Long[] tmp = new Long[m];
        long pre = 0; int j = 0;
        for (int qi : ord) {
            long q = queries[qi];
            while (j < n && a[j] <= q) pre += a[j++];
            tmp[qi] = q * j - pre + (total - pre) - q * (n - j);
        }
        List<Long> res = new ArrayList<>();
        for (Long v : tmp) res.add(v);
        return res;
    }
}

