var minOperations = function(nums, queries) {
    const a = [...nums].sort((x, y) => x - y);
    const n = a.length;
    const total = a.reduce((x, y) => x + y, 0);
    const ord = queries.map((_, i) => i).sort((x, y) => queries[x] - queries[y]);
    const res = new Array(queries.length);
    let pre = 0, j = 0;
    for (const qi of ord) {
        const q = queries[qi];
        while (j < n && a[j] <= q) pre += a[j++];
        res[qi] = q * j - pre + (total - pre) - q * (n - j);
    }
    return res;
};
